    // 기본 생성자 업데이트
    public Point(User user, int amount, String reason) {
        this.user = user;
        this.amount = amount;
        this.remainingAmount = amount; // 초기 남은 금액은 전체 금액
        this.reason = reason;
        this.expirationDate = LocalDate.now().plusDays(90); // 생성 시점부터 90일 후
        this.status = PointStatus.AVAILABLE; // 기본 상태는 사용가능
    }

